import{_ as p,a0 as l,w as o,s as d,ao as c,I as i,x as n,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"查看遠程 Linux 系統中某個端口是否開啓的 3 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"查看遠程 Linux 系統中某個端口是否開啓的 3 種方法 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"查看遠程 Linux 系統中某個端口是否開啓的 3 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"查看遠程 Linux 系統中某個端口是否開啓的 3 種方法 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System","title":"查看遠程 Linux 系統中某個端口是否開啓的 3 種方法","tag":"201904","desc":""},"relativePath":"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System.md","filePath":"[post].md"}'),r={name:"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System.md"};function h(u,s,g,k,b,m){const e=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="查看遠程-linux-系統中某個端口是否開啓的-3-種方法" tabindex="-1">查看遠程 Linux 系統中某個端口是否開啓的 3 種方法 <a class="header-anchor" href="#查看遠程-linux-系統中某個端口是否開啓的-3-種方法" aria-label="Permalink to “查看遠程 Linux 系統中某個端口是否開啓的 3 種方法”">​</a></h1><p>這是一個很重要的話題，不僅對 Linux 管理員而言，對於我們大家而言也非常有幫助。我的意思是説對於工作在 IT 基礎設施行業的用户來説，瞭解這個話題也是非常有用的。他們需要在執行下一步操作前，檢查 Linux 服務器上某個端口是否開啓。</p><p>假如這個端口沒有被開啓，則他們會直接找 Linux 管理員去開啓它。如果這個端口已經開啓了，則我們需要和應用團隊來商量下一步要做的事。</p><p>在本篇文章中，我們將向你展示如何檢查某個端口是否開啓的 3 種方法。</p><p>這個目標可以使用下面的 Linux 命令來達成：</p><ul><li><code>nc</code>：netcat 是一個簡單的 Unix 工具，它使用 TCP 或 UDP 協議去讀寫網絡連接間的數據。</li><li><code>nmap</code>：（“Network Mapper”）是一個用於網絡探索和安全審計的開源工具，被設計用來快速地掃描大規模網絡。</li><li><code>telnet</code>：被用來交互地通過 TELNET 協議與另一台主機通信。</li></ul><h3 id="如何使用-nc-netcat-命令來查看遠程-linux-系統中某個端口是否開啓" tabindex="-1">如何使用 nc（netcat）命令來查看遠程 Linux 系統中某個端口是否開啓？ <a class="header-anchor" href="#如何使用-nc-netcat-命令來查看遠程-linux-系統中某個端口是否開啓" aria-label="Permalink to “如何使用 nc（netcat）命令來查看遠程 Linux 系統中某個端口是否開啓？”">​</a></h3><p><code>nc</code> 即 <code>netcat</code>。<code>netcat</code> 是一個簡單的 Unix 工具，它使用 TCP 或 UDP 協議去讀寫網絡連接間的數據。</p><p>它被設計成為一個可信賴的後端工具，可被直接使用或者簡單地被其他程序或腳本調用。</p><p>與此同時，它也是一個富含功能的網絡調試和探索工具，因為它可以創建你所需的幾乎所有類型的連接，並且還擁有幾個內置的有趣功能。</p><p><code>netcat</code> 有三類功能模式，它們分別為連接模式、監聽模式和隧道模式。</p><p><code>nc</code>（<code>netcat</code>）命令的一般語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nc [-options] [HostName or IP] [PortNumber]</span></span></code></pre></div><p>在下面的例子中，我們將檢查遠程 Linux 系統中的 22 端口是否開啓。</p><p>假如端口是開啓的，你將獲得類似下面的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nc -zvw3 192.168.1.8 22</span></span>
<span class="line"><span>Connection to 192.168.1.8 22 port [tcp/ssh] succeeded!</span></span></code></pre></div><p>命令詳解：</p><ul><li><code>nc</code>：即執行的命令主體；</li><li><code>z</code>：零 I/O 模式（被用來掃描）；</li><li><code>v</code>：顯式地輸出；</li><li><code>w3</code>：設置超時時間為 3 秒；</li><li><code>192.168.1.8</code>：目標系統的 IP 地址；</li><li><code>22</code>：需要驗證的端口。</li></ul><p>當檢測到端口沒有開啓，你將獲得如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nc -zvw3 192.168.1.95 22</span></span>
<span class="line"><span>nc: connect to 192.168.1.95 port 22 (tcp) failed: Connection refused</span></span></code></pre></div><h3 id="如何使用-nmap-命令來查看遠程-linux-系統中某個端口是否開啓" tabindex="-1">如何使用 nmap 命令來查看遠程 Linux 系統中某個端口是否開啓？ <a class="header-anchor" href="#如何使用-nmap-命令來查看遠程-linux-系統中某個端口是否開啓" aria-label="Permalink to “如何使用 nmap 命令來查看遠程 Linux 系統中某個端口是否開啓？”">​</a></h3><p><code>nmap</code>（“Network Mapper”）是一個用於網絡探索和安全審計的開源工具，被設計用來快速地掃描大規模網絡，儘管對於單個主機它也同樣能夠正常工作。</p><p><code>nmap</code> 以一種新穎的方式，使用裸 IP 包來決定網絡中的主機是否可達，這些主機正提供什麼服務（應用名和版本號），它們運行的操作系統（系統的版本），它們正在使用的是什麼包過濾軟件或者防火牆，以及其他額外的特性。</p><p>儘管 <code>nmap</code> 通常被用於安全審計，許多系統和網絡管理員發現在一些日常任務（例如羅列網絡資產、管理服務升級的計劃、監視主機或者服務是否正常運行）中，它也同樣十分有用。</p><p><code>nmap</code> 的一般語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmap [-options] [HostName or IP] [-p] [PortNumber]</span></span></code></pre></div><p>假如端口是開啓的，你將獲得如下的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nmap 192.168.1.8 -p 22</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Starting Nmap 7.70 ( https://nmap.org ) at 2019-03-16 03:37 IST Nmap scan report for 192.168.1.8 Host is up (0.00031s latency).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PORT STATE SERVICE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>22/tcp open ssh </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Nmap done: 1 IP address (1 host up) scanned in 13.06 seconds</span></span></code></pre></div><p>假如端口沒有開啓，你將得到類似下面的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nmap 192.168.1.8 -p 80</span></span>
<span class="line"><span>Starting Nmap 7.70 ( https://nmap.org ) at 2019-03-16 04:30 IST</span></span>
<span class="line"><span>Nmap scan report for 192.168.1.8</span></span>
<span class="line"><span>Host is up (0.00036s latency).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PORT   STATE  SERVICE</span></span>
<span class="line"><span>80/tcp closed http</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Nmap done: 1 IP address (1 host up) scanned in 13.07 seconds</span></span></code></pre></div><h3 id="如何使用-telnet-命令來查看遠程-linux-系統中某個端口是否開啓" tabindex="-1">如何使用 telnet 命令來查看遠程 Linux 系統中某個端口是否開啓？ <a class="header-anchor" href="#如何使用-telnet-命令來查看遠程-linux-系統中某個端口是否開啓" aria-label="Permalink to “如何使用 telnet 命令來查看遠程 Linux 系統中某個端口是否開啓？”">​</a></h3><p><code>telnet</code> 命令被用來交互地通過 TELNET 協議與另一台主機通信。</p><p><code>telnet</code> 命令的一般語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet [HostName or IP] [PortNumber]</span></span></code></pre></div><p>假如探測成功，你將看到類似下面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet 192.168.1.9 22</span></span>
<span class="line"><span>Trying 192.168.1.9...</span></span>
<span class="line"><span>Connected to 192.168.1.9.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>SSH-2.0-OpenSSH_5.3</span></span>
<span class="line"><span>^]</span></span>
<span class="line"><span>Connection closed by foreign host.</span></span></code></pre></div><p>假如探測失敗，你將看到類似下面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet 192.168.1.9 80</span></span>
<span class="line"><span>Trying 192.168.1.9...</span></span>
<span class="line"><span>telnet: Unable to connect to remote host: Connection refused</span></span></code></pre></div><p>當前，我們只找到上面 3 種方法來查看遠程 Linux 系統中某個端口是否開啓，假如你發現了其他方法可以達到相同的目的，請在下面的評論框中告知我們。</p><hr>`,40)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),a(e,{href:"https://www.2daygeek.com/how-to-check-whether-a-port-is-open-on-the-remote-linux-system-server/"},{default:t(()=>[...s[0]||(s[0]=[n("https://www.2daygeek.com/how-to-check-whether-a-port-is-open-on-the-remote-linux-system-server/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),a(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:t(()=>[...s[2]||(s[2]=[n("Magesh Maruthamuthu",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),a(e,{href:"https://github.com/FSSlc"},{default:t(()=>[...s[4]||(s[4]=[n("FSSlc",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const y=p(r,[["render",h]]);export{T as __pageData,y as default};
